# Caching Strategy with Proper Cache Invalidation

## Overview

Effective caching requires balancing **performance** vs **consistency**. For dynamic content, you need strategies that minimize stale data while avoiding unnecessary cache misses.

## Core Strategies

### 1. Time-Based Invalidation (TTL)

```python
from functools import wraps
import time
import redis

def cached(ttl_seconds=300):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            cache_key = f"{func.__name__}:{','.join(map(str, args))}"

            # Try to get from cache
            cached_data = redis_client.get(cache_key)
            if cached_data:
                return json.loads(cached_data.decode())

            # Compute and store
            result = func(*args, **kwargs)
            redis_client.setex(cache_key, ttl_seconds, json.dumps(result))
            return result

        return wrapper
    return decorator

# Usage
@cached(ttl_seconds=60)
def get_user_data(user_id):
    # Fetch from database
    return {"id": user_id, "name": "John"}
```

**Trade-offs:** Simple to implement but may serve stale data during high traffic.

### 2. Event-Driven Invalidation (Cache Aside Pattern)

```python
import redis
from contextlib import contextmanager

class CacheManager:
    def __init__(self, redis_client):
        self.redis = redis_client

    @contextmanager
    def cache_with_invalidation(self, key, ttl=300):
        # Get current value
        cached_value = self.redis.get(key)

        try:
            yield cached_value  # Use the value

            # On exit, invalidate if modified
            self.redis.delete(key)
        except Exception as e:
            # Handle error - don't delete on failure
            pass

    def invalidate_by_pattern(self, prefix):
        keys = self.redis.keys(f"{prefix}*")
        for key in keys:
            self.redis.delete(key)

# Usage
cache_manager = CacheManager(redis_client)

with cache_manager.cache_with_invalidation("user:123", ttl=60):
    user_data = get_user_from_db(123)  # Compute fresh data
```

**Trade-offs:** Better consistency but requires application-level coordination.

### 3. Write-Through Caching

```python
class WriteThroughCache:
    def __init__(self, redis_client):
        self.redis = redis_client

    def set(self, key, value, ttl=300):
        # Store in cache AND database simultaneously
        self.redis.setex(key, ttl, value)
        db_store(value)  # Write to primary storage

    def get(self, key):
        return self.redis.get(key)
```

**Trade-offs:** Ensures consistency but adds write latency.

### 4. Cache-Aside with Optimistic Locking

```python
import redis
from functools import wraps

def optimistic_cache(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        cache_key = f"{func.__name__}:{','.join(map(str, args))}"

        # Check for stale data
        cached_data = redis_client.get(cache_key)
        if not cached_data:
            return func(*args, **kwargs)  # Compute fresh

        # Verify timestamp
        cache_entry = redis_client.get(f"{cache_key}:meta")
        if cache_entry and time.time() - int(cache_entry) > ttl:
            return func(*args, **kwargs)

        return json.loads(cached_data.decode())

    return wrapper

# Usage
@optimistic_cache(ttl=300)
def get_product(product_id):
    # Fetch from database with optimistic locking
    product = db.get_with_lock("product", product_id)
    return product
```

**Trade-offs:** Good for high-traffic scenarios but adds complexity.

## Best Practices

1. **Cache Tiering**: Use CDN for static assets, Redis for session data

